const std = @import("std");

const JsonValue = std.json.Value;
const Allocator = std.mem.Allocator;

const TaskType = enum {
    ERROR_ANALYSIS,
    FAST_CODE_GENERATION,
};

const ProviderResponse = struct {
    content: []ContentItem,
};

const ContentItem = struct {
    text: ContentText,
};

const ContentText = union(enum) {
    string: []const u8,
    items: []TextItem,
};

const TextItem = struct {
    text: []const u8,
};

const ProviderRouter = struct {
    allocator: Allocator,

    pub fn init(allocator: Allocator) ProviderRouter {
        return .{ .allocator = allocator };
    }

    pub fn deinit(self: *ProviderRouter) void {
        _ = self;
    }

    pub fn generate(self: *ProviderRouter, prompt: []const u8, task_type: TaskType, max_tokens: usize, temperature: f64) !ProviderResponse {
        _ = self;
        _ = prompt;
        _ = task_type;
        _ = max_tokens;
        _ = temperature;
        return .{
            .content = &[_]ContentItem{
                .{
                    .text = .{ .string = "" },
                },
            },
        };
    }

    pub fn close(self: *ProviderRouter) !void {
        _ = self;
    }
};

const ExecutionResult = struct {
    exit_code: i32,
    stdout: []const u8,
    stderr: []const u8,
};

const SandboxClient = struct {
    allocator: Allocator,

    pub fn init(allocator: Allocator) SandboxClient {
        return .{ .allocator = allocator };
    }

    pub fn deinit(self: *SandboxClient) void {
        _ = self;
    }

    pub fn execute(
        self: *SandboxClient,
        repo_snapshot: []const u8,
        commands: []const []const u8,
        environment: std.StringHashMap([]const u8),
        resource_limits: ResourceLimits,
        network_policy: NetworkPolicy,
    ) !ExecutionResult {
        _ = self;
        _ = repo_snapshot;
        _ = commands;
        _ = environment;
        _ = resource_limits;
        _ = network_policy;
        return .{
            .exit_code = 1,
            .stdout = "",
            .stderr = "",
        };
    }

    pub fn close(self: *SandboxClient) !void {
        _ = self;
    }
};

const ResourceLimits = struct {
    cpu: i32,
    memory_mb: i32,
    timeout_seconds: i32,
};

const NetworkPolicy = struct {
    allow_outbound: bool,
};

const SelfHealingAgent = struct {
    allocator: Allocator,
    provider_router: ProviderRouter,
    sandbox_client: SandboxClient,
    max_iterations: usize,

    pub fn init(allocator: Allocator) SelfHealingAgent {
        return .{
            .allocator = allocator,
            .provider_router = ProviderRouter.init(allocator),
            .sandbox_client = SandboxClient.init(allocator),
            .max_iterations = 5,
        };
    }

    pub fn deinit(self: *SelfHealingAgent) void {
        self.provider_router.deinit();
        self.sandbox_client.deinit();
    }

    pub fn heal(self: *SelfHealingAgent, error_context: JsonValue) !JsonValue {
        var iteration: usize = 0;
        var current_error = error_context;

        while (iteration < self.max_iterations) {
            iteration += 1;

            const analysis = try self.analyzeError(current_error);

            if (try categoryRequiresManualIntervention(analysis)) {
                var obj = std.json.ObjectMap.init(self.allocator);
                try obj.put("success", JsonValue{ .bool = false });

                const category = try getStringField(analysis, "category");
                const reason = try std.fmt.allocPrint(self.allocator, "Error category '{s}' requires manual intervention", .{category});
                try obj.put("reason", JsonValue{ .string = reason });
                try obj.put("analysis", analysis);
                try obj.put("iterations", JsonValue{ .integer = @as(i64, @intCast(iteration)) });
                return JsonValue{ .object = obj };
            }

            const patch = try self.generatePatch(current_error, analysis);
            const test_result = try self.testPatch(patch, current_error);

            if (try getBoolField(test_result, "success")) {
                var obj = std.json.ObjectMap.init(self.allocator);
                try obj.put("success", JsonValue{ .bool = true });
                try obj.put("patch", patch);
                try obj.put("analysis", analysis);
                try obj.put("iterations", JsonValue{ .integer = @as(i64, @intCast(iteration)) });
                try obj.put("test_result", test_result);
                return JsonValue{ .object = obj };
            }

            var next_error = std.json.ObjectMap.init(self.allocator);
            try next_error.put("original_error", error_context);
            try next_error.put("patch_attempt", patch);
            try next_error.put("test_result", test_result);
            try next_error.put("iteration", JsonValue{ .integer = @as(i64, @intCast(iteration)) });
            current_error = JsonValue{ .object = next_error };
        }

        var obj = std.json.ObjectMap.init(self.allocator);
        try obj.put("success", JsonValue{ .bool = false });
        try obj.put("reason", JsonValue{ .string = "Maximum iterations reached without successful fix" });
        try obj.put("iterations", JsonValue{ .integer = @as(i64, @intCast(iteration)) });
        try obj.put("last_error", current_error);
        return JsonValue{ .object = obj };
    }

    pub fn analyzeError(self: *SelfHealingAgent, error_context: JsonValue) !JsonValue {
        const context_json = try stringifyJson(self.allocator, error_context);
        const prompt = try std.fmt.allocPrint(
            self.allocator,
            \\You are an error analysis agent with deep reasoning capabilities. Analyze the following error and provide a root cause analysis.
            \\
            \\Error Context:
            \\{s}
            \\
            \\Categorize the error into one of:
            \\- compile: Syntax or compilation errors
            \\- runtime: Runtime exceptions
            \\- test: Test failures
            \\- flake: Non-deterministic failures
            \\- dependency: Missing or incompatible dependencies
            \\- environment: Environment configuration issues
            \\
            \\Provide:
            \\1. Error category
            \\2. Root cause explanation
            \\3. Affected components
            \\4. Recommended fix strategy
            \\5. Confidence level (0-1)
            \\
            \\Return JSON:
            \\{{
            \\  "category": "compile|runtime|test|flake|dependency|environment",
            \\  "root_cause": "detailed explanation",
            \\  "affected_components": ["component1", "component2"],
            \\  "fix_strategy": "recommended approach",
            \\  "confidence": 0.95
            \\}}
            ,
            .{context_json},
        );

        const response = try self.provider_router.generate(prompt, .ERROR_ANALYSIS, 2048, 0.3);
        var content = getResponseContent(response);

        const parsed = parseJsonLoosely(self.allocator, content) catch {
            var obj = std.json.ObjectMap.init(self.allocator);
            try obj.put("category", JsonValue{ .string = "unknown" });
            try obj.put("root_cause", JsonValue{ .string = "Failed to parse analysis" });
            try obj.put("affected_components", JsonValue{ .array = std.ArrayList(JsonValue).init(self.allocator) });
            try obj.put("fix_strategy", JsonValue{ .string = "Manual review required" });
            try obj.put("confidence", JsonValue{ .float = 0.0 });
            return JsonValue{ .object = obj };
        };

        return parsed;
    }

    pub fn generatePatch(self: *SelfHealingAgent, error_context: JsonValue, analysis: JsonValue) !JsonValue {
        const context_json = try stringifyJson(self.allocator, error_context);
        const analysis_json = try stringifyJson(self.allocator, analysis);

        const prompt = try std.fmt.allocPrint(
            self.allocator,
            \\You are a code repair agent. Generate a minimal patch to fix the identified error.
            \\
            \\Error Context:
            \\{s}
            \\
            \\Analysis:
            \\{s}
            \\
            \\Generate a minimal, targeted patch that:
            \\1. Addresses the root cause
            \\2. Maintains existing functionality
            \\3. Follows code conventions
            \\4. Includes no placeholders or TODOs
            \\
            \\Return JSON:
            \\{{
            \\  "files": [
            \\    {{"path": "file/path", "changes": [{{"line": 10, "old": "old code", "new": "new code"}}]}}
            \\  ],
            \\  "explanation": "why this fixes the issue"
            \\}}
            ,
            .{ context_json, analysis_json },
        );

        const response = try self.provider_router.generate(prompt, .FAST_CODE_GENERATION, 2048, 0.3);
        var content = getResponseContent(response);

        const parsed = parseJsonLoosely(self.allocator, content) catch {
            var obj = std.json.ObjectMap.init(self.allocator);
            try obj.put("files", JsonValue{ .array = std.ArrayList(JsonValue).init(self.allocator) });
            try obj.put("explanation", JsonValue{ .string = "Failed to generate patch" });
            return JsonValue{ .object = obj };
        };

        return parsed;
    }

    pub fn testPatch(self: *SelfHealingAgent, patch: JsonValue, error_context: JsonValue) !JsonValue {
        _ = patch;

        const repo_snapshot = getOptionalStringField(error_context, "repo_snapshot") orelse "";
        const test_commands = try getTestCommands(self.allocator, error_context);

        var environment = std.StringHashMap([]const u8).init(self.allocator);

        const execution_result = try self.sandbox_client.execute(
            repo_snapshot,
            test_commands,
            environment,
            .{
                .cpu = 2,
                .memory_mb = 4096,
                .timeout_seconds = 300,
            },
            .{
                .allow_outbound = false,
            },
        );

        const success = execution_result.exit_code == 0;

        var obj = std.json.ObjectMap.init(self.allocator);
        try obj.put("success", JsonValue{ .bool = success });
        try obj.put("exit_code", JsonValue{ .integer = execution_result.exit_code });
        try obj.put("stdout", JsonValue{ .string = execution_result.stdout });
        try obj.put("stderr", JsonValue{ .string = execution_result.stderr });
        return JsonValue{ .object = obj };
    }

    pub fn close(self: *SelfHealingAgent) !void {
        try self.provider_router.close();
        try self.sandbox_client.close();
    }
};

fn getResponseContent(response: ProviderResponse) []const u8 {
    if (response.content.len == 0) return "";
    const first = response.content;
    return switch (first.text) {
        .string => |s| s,
        .items => |items| if (items.len == 0) "" else items.text,
    };
}

fn stringifyJson(allocator: Allocator, value: JsonValue) ![]const u8 {
    var list = std.ArrayList(u8).init(allocator);
    try std.json.stringify(value, .{ .whitespace = .indent_2 }, list.writer());
    return list.toOwnedSlice();
}

fn parseJsonLoosely(allocator: Allocator, content: []const u8) !JsonValue {
    return parseJsonStrict(allocator, content) catch {
        const start = std.mem.indexOfScalar(u8, content, '{') orelse return error.InvalidJson;
        const end_inclusive = std.mem.lastIndexOfScalar(u8, content, '}') orelse return error.InvalidJson;
        if (end_inclusive < start) return error.InvalidJson;
        return parseJsonStrict(allocator, content[start .. end_inclusive + 1]);
    };
}

fn parseJsonStrict(allocator: Allocator, text: []const u8) !JsonValue {
    var parsed = try std.json.parseFromSlice(JsonValue, allocator, text, .{});
    return parsed.value;
}

fn categoryRequiresManualIntervention(analysis: JsonValue) !bool {
    const category = try getStringField(analysis, "category");
    return std.mem.eql(u8, category, "environment") or std.mem.eql(u8, category, "dependency") or std.mem.eql(u8, category, "flake");
}

fn getStringField(value: JsonValue, key: []const u8) ![]const u8 {
    switch (value) {
        .object => |obj| {
            const field = obj.get(key) orelse return error.MissingField;
            return switch (field) {
                .string => |s| s,
                else => error.InvalidFieldType,
            };
        },
        else => return error.InvalidFieldType,
    }
}

fn getOptionalStringField(value: JsonValue, key: []const u8) ?[]const u8 {
    return switch (value) {
        .object => |obj| blk: {
            const field = obj.get(key) orelse break :blk null;
            break :blk switch (field) {
                .string => |s| s,
                else => null,
            };
        },
        else => null,
    };
}

fn getBoolField(value: JsonValue, key: []const u8) !bool {
    switch (value) {
        .object => |obj| {
            const field = obj.get(key) orelse return error.MissingField;
            return switch (field) {
                .bool => |b| b,
                else => error.InvalidFieldType,
            };
        },
        else => return error.InvalidFieldType,
    }
}

fn getTestCommands(allocator: Allocator, error_context: JsonValue) ![]const []const u8 {
    switch (error_context) {
        .object => |obj| {
            const field = obj.get("test_commands") orelse {
                var list = try allocator.alloc([]const u8, 1);
                list = "pytest";
                return list;
            };
            switch (field) {
                .array => |arr| {
                    if (arr.items.len == 0) {
                        var list = try allocator.alloc([]const u8, 1);
                        list = "pytest";
                        return list;
                    }
                    var out = try allocator.alloc([]const u8, arr.items.len);
                    for (arr.items, 0..) |item, i| {
                        out[i] = switch (item) {
                            .string => |s| s,
                            else => return error.InvalidFieldType,
                        };
                    }
                    return out;
                },
                else => {
                    var list = try allocator.alloc([]const u8, 1);
                    list = "pytest";
                    return list;
                },
            }
        },
        else => {
            var list = try allocator.alloc([]const u8, 1);
            list = "pytest";
            return list;
        },
    }
}

pub fn main() !void {
    var gpa_state = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa_state.deinit();
    const allocator = gpa_state.allocator();

    var agent = SelfHealingAgent.init(allocator);
    defer agent.deinit();

    const sample_error = blk: {
        var obj = std.json.ObjectMap.init(allocator);
        try obj.put("repo_snapshot", JsonValue{ .string = "" });
        var commands = std.ArrayList(JsonValue).init(allocator);
        try commands.append(JsonValue{ .string = "pytest" });
        try obj.put("test_commands", JsonValue{ .array = commands });
        break :blk JsonValue{ .object = obj };
    };

    _ = try agent.heal(sample_error);
    try agent.close();
}
